async function retryOpen(){if(openContext&&!initializing.value&&!busy.value)await initializeOpen(openContext)}
async function changeFactory(value:string){const session=openEpoch,epoch=++optionEpoch;if(form.lines.length){try{await ElMessageBox.confirm('变更工厂将清空物料明细，是否继续？','提示')}catch{return}}if(disposed||session!==openEpoch||epoch!==optionEpoch||busy.value)return;invalidateDetail();form.factoryId=value;form.warehouseId='';form.operatorIds=[];form.keeperId='';form.recipientId='';form.inspectorId='';form.reviewerId='';form.sourceOrderId='';form.workOrderCustomer='';form.workOrderId='';form.batchId='';form.lines=[];itemId.value='';processId.value='';items.value=[];await reloadOptions()}
function typeChanged(){invalidateDetail();form.lines=[];form.batchId='';form.batchVersion=null;form.settle=false;form.sourceOrderId='';form.workOrderCustomer='';form.workOrderId='';itemId.value='';processId.value='';items.value=[]}
async function sourceOrderChanged(){invalidateDetail();form.lines=[];selected.value=[];form.settle=false;form.batchId='';form.workOrderId='';form.workOrderCustomer='';itemId.value='';processId.value='';items.value=[];const source=sourceOrders.value.find(o=>o.id===form.sourceOrderId);if(!source)return;form.batchId=source.batchId;await batchChanged()}
async function orderChanged(){invalidateDetail();const epoch=detailEpoch,session=openEpoch,work=form.workOrderId,factory=form.factoryId,type=form.type;const current=()=>!disposed&&visible.value&&session===openEpoch&&epoch===detailEpoch&&work===form.workOrderId&&factory===form.factoryId&&type===form.type;form.batchId='';form.lines=[];form.settle=false;if(!work)return;detailLoading.value=true;try{const detail=(await warehouseWorkOrderContext(factory,work,current)).data;if(!current())return;if(detail.workOrderId!==String(work)||detail.factoryId!==String(factory))throw Error('工单上下文不匹配');items.value=detail.items;form.workOrderCustomer=detail.customer??''}catch{if(current())ElMessage.error('工单详情加载失败，请重新选择工单重试')}finally{if(current())detailLoading.value=false}}
async function batchChanged(){const batchId=form.batchId,b=batches.value.find(o=>o.id===batchId);invalidateDetail();const epoch=detailEpoch,session=openEpoch,factory=form.factoryId,type=form.type,sourceOrder=form.sourceOrderId;form.batchVersion=b?.version;form.lines=[];form.settle=false;if(!b)return;const work=b.workOrderId;form.workOrderId=work;const current=()=>!disposed&&visible.value&&session===openEpoch&&epoch===detailEpoch&&factory===form.factoryId&&type===form.type&&sourceOrder===form.sourceOrderId&&work===form.workOrderId&&batches.value.some(o=>o.id===batchId&&o.workOrderId===work&&o.itemId===b.itemId&&o.processId===b.processId);detailLoading.value=true;try{const detail=(await warehouseWorkOrderContext(factory,work,current)).data;if(!current())return;if(detail.workOrderId!==String(work)||detail.factoryId!==String(factory)||!detail.items.some(o=>o.id===b.itemId&&o.plans.some(p=>p.processId===b.processId)))throw Error('批次工单上下文不匹配');items.value=detail.items;form.workOrderCustomer=detail.customer??'';itemId.value=b.itemId;processId.value=b.processId;form.batchId=batchId;form.batchVersion=b.version}catch{if(current()){form.batchId='';ElMessage.error('批次详情加载失败，请重新选择重试')}}finally{if(current())detailLoading.value=false}}

async function editLine(row?:Row){if(dependenciesLoading.value||checkingStock.value)return;if(returning.value&&form.type==='RAW_RETURN'&&!form.sourceOrderId){ElMessage.error('请先选择对应出库工单');return}const category=line.category;lineIndex.value=row?form.lines.indexOf(row):-1;for(const k of Object.keys(line))delete line[k];Object.assign(line,row?{...row}:{category:opening.value?category||'RAW':categoryForType(),netWeight:'',quantity:0,grossWeight:'',impurity:'',purity:'',batchNo:''});if(kind.value==='IN'&&!opening.value&&form.workOrderId&&line.category!=='RAW')line.organization=form.workOrderCustomer??'';lineVisible.value=true;if(form.type==='RAW_RETURN')await refreshReturnSources(true)}
const selectedReturnSource=computed(()=>sources.value.find(o=>o.id===line.sourceLineId));
function sourceAvailable(source:Row){try{return rawReturnAvailable(source,sources.value,form.lines??[],lineIndex.value)}catch{return '0.000000'}}
function returnLimitReason(source:Row){if(Number(source.batchRemainingWeight)<0||Number(source.remainingWeight)<0)return '历史重量异常，请人工核对';if(Number(source.returnableWeight)===0&&Number(source.remainingWeight)>0&&Number(source.batchRemainingWeight)>0)return '批次已结算、已冲销或状态发生变化，不能新增还库';return '可退额度已用完（已扣除产出、已还料及本单其他待还明细）'}
async function refreshReturnSources(requireLine=false){
 const ticket=++returnEpoch,session=openEpoch,detail=detailEpoch,factory=form.factoryId,warehouse=form.warehouseId,batch=form.batchId,sourceOrder=form.sourceOrderId,type=form.type;
 const current=()=>!disposed&&visible.value&&(!requireLine||lineVisible.value)&&ticket===returnEpoch&&session===openEpoch&&detail===detailEpoch&&factory===form.factoryId&&warehouse===form.warehouseId&&batch===form.batchId&&sourceOrder===form.sourceOrderId&&type===form.type;
 refreshingReturn.value=true;returnLoadError.value=false;
 try{const response=await warehouseOptions('out-lines',factory,undefined,current);if(!current())return false;sources.value=response.data;return true}
 catch{if(current()){returnLoadError.value=true;ElMessage.error('可退额度加载失败，请重试')}return false}
 finally{if(current())refreshingReturn.value=false}
}
async function validateRawReturns(incoming:Row[],editingIndex=-1,replaceAll=false,requireLine=false){
 if(!await refreshReturnSources(requireLine))return false;
 const pending:Row[]=[],rows=[...(replaceAll?[]:form.lines.filter((_:Row,index:number)=>index!==editingIndex)),...incoming];
 for(const row of rows){const source=sources.value.find(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId&&o.batchId===form.batchId&&o.warehouseId===form.warehouseId&&o.type==='PRODUCTION_OUT'&&o.category==='RAW');if(!source){ElMessage.error('原出库来源已失效，请重新选择');return false}const error=rawReturnError(source,sources.value,pending,row.netWeight);if(error){ElMessage.error(error);return false}pending.push(row)}
 return true
}
function materialChoiceLabel(option:Row){if(out.value&&option.category==='RAW')return [option.code||'',option.name,String(option.organization??'').trim()||'未填写单位名称'].join(' / ');const label=(option.code?option.code+' / ':'')+option.name;return returning.value?option.name:label+' / '+(String(option.specification??'').trim()||'未填写规格型号')}
function choiceChanged(value:string){const o=choices.value.find(o=>o.id===value);if(!o)return;if(out.value)line.organization=o.organization??'';line.code=o.code||'';line.name=o.name;line.specification=o.specification||'';line.unit='件';if(out.value){line.inventoryId=o.id;line.category=o.category;line.referenceId=o.referenceId}else if(returning.value){line.organization=o.organization??'';line.sourceLineId=o.id;line.category=o.category;line.referenceId=o.referenceId;line.batchNo=o.batchNo}else{line.referenceId=o.id}if(line.category==='RAW')line.quantity=0;else if(!line.quantity)line.quantity=1}
function deriveNet(){const valid=(value:string)=>/^\d{1,14}(\.\d{0,6})?$/.test(value);if(line.grossWeight&&valid(line.grossWeight)&&(!line.impurity||valid(line.impurity))){const units=(value:string)=>{const [integer,fraction='']=value.split('.');return BigInt(integer||'0')*1000000n+BigInt(fraction.padEnd(6,'0'))};const result=units(line.grossWeight)-units(line.impurity||'0'),positive=result<0n?-result:result;line.netWeight=(result<0n?'-':'')+(positive/1000000n)+'.'+(positive%1000000n).toString().padStart(6,'0')}}
function weightError(key:string){const value=String(line[key]??'');if(!value)return key==='netWeight'?'请输入实测净重':'';if(!/^[0-9]{1,14}(\.[0-9]{1,6})?$/.test(value))return '请输入非负数字，整数最多14位、小数最多6位';if(key==='netWeight'&&Number(value)<=0)return '实测净重必须大于0';return ''}
function purityError(){if(line.category!=='SEMI')return '';const value=String(line.purity??'');if(!value)return '';if(!/^\d{1,6}(\.\d{1,6})?$/.test(value))return '请输入数字，最多6位小数';if(Number(value)>100)return '纯度请输入0～100之间的数字';return ''}
function weightUnits(value:string){const [integer,fraction='']=value.split('.');return BigInt(integer)*1000000n+BigInt(fraction.padEnd(6,'0'))}
async function validateOutgoingLines(incoming:Row[],editingIndex=-1){
 const session=openEpoch,factory=form.factoryId,warehouse=form.warehouseId,type=form.type;
 const response=await warehouseOptions('stocks',factory);if(disposed||session!==openEpoch||factory!==form.factoryId||warehouse!==form.warehouseId||type!==form.type)return false;stocks.value=response.data
 const pending=form.lines.filter((_:Row,index:number)=>index!==editingIndex)
 for(const [index,row]of incoming.entries()){
  const stock=stocks.value.find(o=>o.id===row.inventoryId&&o.warehouseId===form.warehouseId&&o.category===row.category)
  if(!stock){ElMessage.error('所选库存已失效或不属于当前库房，请重新选择');return false}
  const error=stockAvailabilityError(stock as {netWeight:string;quantity:number;category:string},row,pending)
  if(error){ElMessage.error((incoming.length>1?'导入第'+(index+1)+'条：':'')+error);return false}
  pending.push(row)
 }
 return true
}
async function confirmLine(){
 const productError=outputProductError([line]);if(productError){ElMessage.error(productError);return}
 if(purityError()){ElMessage.error(purityError());return}
 if(kind.value==='IN'&&!opening.value&&form.workOrderId&&line.category!=='RAW')line.organization=form.workOrderCustomer??'';if(checkingStock.value||refreshingReturn.value||returnLoadError.value)return;for(const key of ['grossWeight','impurity','netWeight']){const error=weightError(key);if(error){ElMessage.error(error);return}}if(line.grossWeight){const gross=weightUnits(String(line.grossWeight)),impurity=weightUnits(String(line.impurity||'0'));if(impurity>gross){ElMessage.error('杂质不能超过毛重');return}if(gross-impurity!==weightUnits(String(line.netWeight))){ElMessage.error('实测净重必须等于毛重减杂质');return}}if(!line.choiceId||!/^\d+(\.\d{1,6})?$/.test(String(line.netWeight))||Number(line.netWeight)<=0||(line.category!=='RAW'&&(!Number.isInteger(line.quantity)||line.quantity<1))){ElMessage.error('请选择物料并填写正数净重及合法数量');return}const session=openEpoch;if(form.type==='RAW_RETURN'){checkingStock.value=true;try{if(!await validateRawReturns([{...line}],lineIndex.value,false,true))return}finally{if(!disposed&&session===openEpoch)checkingStock.value=false}}if(out.value){checkingStock.value=true;try{if(!await validateOutgoingLines([line],lineIndex.value))return}catch{ElMessage.error('库存校验失败，请重试，本条物料尚未加入清单');return}finally{if(!disposed&&session===openEpoch)checkingStock.value=false}}if(disposed||session!==openEpoch)return;if(lineIndex.value<0)form.lines.push({...line});else form.lines[lineIndex.value]={...line};lineVisible.value=false}
function removeLines(){form.lines=form.lines.filter((r:Row)=>!selected.value.includes(r));selected.value=[]}
async function download(){const data=await request({url:'/metal/warehouse-order/template',params:kind.value==='IN'&&!opening.value?{type:form.type,batchBound:!!form.batchId}:undefined,responseType:'blob'});const url=URL.createObjectURL(data as unknown as Blob);const a=document.createElement('a');a.href=url;a.download='仓储物料模板.xlsx';a.click();URL.revokeObjectURL(url)}
async function importFile(event:Event){if(returning.value&&form.type==='RAW_RETURN'&&!form.sourceOrderId){ElMessage.error('请先选择对应出库工单');(event.target as HTMLInputElement).value='';return}const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||dependenciesLoading.value||busy.value)return;const session=openEpoch,epoch=++optionEpoch;const outputContext=[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type];const current=()=>!disposed&&session===openEpoch&&epoch===optionEpoch&&outputContext.every((v,i)=>v===[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type][i]);loading.value=true;try{const r=await importWarehouseLines(file,{...form,itemId:itemId.value,processId:processId.value});if(!current())return;if(form.lines.length+(r as any).data.length>1000){ElMessage.error('物料清单合计最多1000行，本次导入未追加');return}if(returning.value&&form.type==='RAW_RETURN'&&(r as any).data.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId))){ElMessage.error('导入物料必须来自所选出库工单');return}if(form.type==='RAW_RETURN'&&!await validateRawReturns((r as any).data))return;if(out.value&&!await validateOutgoingLines((r as any).data))return;if(!current())return;const productError=outputProductError((r as any).data,true);if(productError){ElMessage.error(productError);return}form.lines.push(...(r as any).data.map((row:Row)=>kind.value==='IN'&&!opening.value&&form.workOrderId&&row.category!=='RAW'?{...row,organization:form.workOrderCustomer??''}:row));ElMessage.success('已填充明细，确认后才会过账')}finally{if(!disposed&&session===openEpoch&&epoch===optionEpoch){loading.value=false;input.value=''}}}
async function save(){if(busy.value||dependenciesLoading.value)return;const productError=outputProductError(form.lines);if(productError){ElMessage.error(productError);return}if(returning.value&&form.type==='RAW_RETURN'&&(!form.sourceOrderId||form.lines.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId)))){ElMessage.error('请选择对应出库工单，物料必须来自该单据');return}if(!form.factoryId||!form.warehouseId||!form.orderDate||(form.type!=='PRODUCTION_OUT'&&!form.operatorIds?.length)||!form.keeperId||!form.lines.length){ElMessage.error('请选择工厂、库房、日期、经办人、仓管员并添加物料');return}if((['PRODUCTION_OUT','RAW_RETURN'].includes(form.type)||form.workOrderId)&&(!form.workOrderId||!itemId.value||!processId.value)){ElMessage.error('请选择生产工单、产品明细和工序');return}if(form.settle&&(!Number.isInteger(form.completedQuantity)||form.completedQuantity<1)){ElMessage.error('请填写正整数实际完成数量');return}const session=openEpoch;busy.value=true;try{if(form.type==='RAW_RETURN'&&!await validateRawReturns(form.lines,-1,true))return;const data={...form,batchId:null,batchVersion:null,itemId:form.workOrderId?itemId.value:null,processId:form.workOrderId?processId.value:null,workOrderId:form.workOrderId||null,recipientId:form.recipientId||null,inspectorId:form.inspectorId||null,reviewerId:form.reviewerId||null,lines:form.lines.map((r:Row)=>({...r,grossWeight:r.grossWeight||null,impurity:r.impurity||null,purity:r.purity||null}))};await warehouseSave(opening.value?'inventory/opening':'warehouse-order',JSON.parse(JSON.stringify(data)));if(disposed||session!==openEpoch)return;visible.value=false;ElMessage.success('单据已生效');emit('saved')}finally{busy.value=false}}
defineExpose({open,cancelOpen})
</script>
